index 00000000..9a9ff439
--- /dev/null
+++ b/src/main/java/org/xbill/DNS/DigestLengths.java
@@ -0,0 +1,18 @@
+// SPDX-License-Identifier: BSD-3-Clause
+package org.xbill.DNS;
+
+import lombok.experimental.UtilityClass;
+
+/** Constants for common Hash/Digest lengths. */
+@UtilityClass
+class DigestLengths {
+  static final int MD5 = 16;
+  static final int SHA1 = 20;
+  static final int SHA224 = 28;
+  static final int SHA256 = 32;
+  static final int SHA384 = 48;
+  static final int SHA512 = 64;
+  static final int GOST3411 = 32;
+  static final int GOST3411_12 = 64;
+  static final int SM3 = 32;
+}
diff --git a/src/main/java/org/xbill/DNS/SSHFPRecord.java b/src/main/java/org/xbill/DNS/SSHFPRecord.java
index 4d7e9715..3025f1aa 100644
--- a/src/main/java/org/xbill/DNS/SSHFPRecord.java
+++ b/src/main/java/org/xbill/DNS/SSHFPRecord.java
@@ -6,0 +7 @@ import java.io.IOException;
+import java.util.function.Function;
@@ -21 +22,12 @@ public class SSHFPRecord extends Record {
-    public static final int DSS = 2;
+
+    /**
+     * Use {@link #DSA}; DSS was a typo in RFC 4255.
+     *
+     * @see <a href="https://errata.rfc-editor.org/eid6266/">Errata-ID: 6266</a>
+     */
+    @Deprecated public static final int DSS = 2;
+
+    public static final int DSA = 2;
+    public static final int ECDSA = 3;
+    public static final int ED25519 = 4;
+    public static final int ED448 = 6;
@@ -27,0 +40 @@ public class SSHFPRecord extends Record {
+    public static final int SHA256 = 2;
@@ -47,0 +61 @@ public class SSHFPRecord extends Record {
+    validateFingerprintLength(IllegalArgumentException::new);
@@ -54,0 +69 @@ public class SSHFPRecord extends Record {
+    validateFingerprintLength(WireParseException::new);
@@ -61,0 +77,21 @@ public class SSHFPRecord extends Record {
+    validateFingerprintLength(st::exception);
+  }
+
+  private <T extends Throwable> void validateFingerprintLength(Function<String, T> exceptionCreator)
+      throws T {
+    int expectedLength = fingerprintLength(digestType);
+    if (expectedLength >= 0 && fingerprint.length != expectedLength) {
+      throw exceptionCreator.apply(
+          "Expected " + expectedLength + " fingerprint bytes, got " + fingerprint.length);
+    }
+  }
+
+  private static int fingerprintLength(int digestType) {
+    switch (digestType) {
+      case Digest.SHA1:
+        return DigestLengths.SHA1;
+      case Digest.SHA256:
+        return DigestLengths.SHA256;
+      default:
+        return -1;
+    }
